import{_ as t,C as r,c as s,o as a,a3 as o,G as i}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Invoice sequence","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/customer-invoices/invoice-sequence.md","filePath":"master/finance/customer-invoices/invoice-sequence.md","lastUpdated":1791902625000}'),c={name:"master/finance/customer-invoices/invoice-sequence.md"};function l(u,e,d,h,m,g){const n=r("ImagePopup");return a(),s("div",null,[e[0]||(e[0]=o('<h1 id="invoice-sequence" tabindex="-1">Invoice sequence <a class="header-anchor" href="#invoice-sequence" aria-label="Permalink to &quot;Invoice sequence&quot;">​</a></h1><p>Every invoice, credit note, bill and payment gets a number. Aureus builds that number from a sequence, so two documents never share the same number. This page explains how the number looks, when it appears and how you can see or change the rule.</p><blockquote><p><strong>In simple words:</strong> A sequence is a numbering machine. Each journal has its own, so invoices and bills count separately.</p></blockquote><h2 id="how-a-number-is-built" tabindex="-1">How a number is built <a class="header-anchor" href="#how-a-number-is-built" aria-label="Permalink to &quot;How a number is built&quot;">​</a></h2><p>The usual format is:</p><p><code>{journal code}/{year}/{number}</code></p><ul><li><strong>Journal code:</strong> The short code of the journal, such as INV for <strong>Customer Invoices</strong>.</li><li><strong>Year:</strong> The year of the document date.</li><li><strong>Number:</strong> A counter with 5 digits. Aureus adds zeros on the left.</li></ul><p>The counter starts again at 1 every year. So the first invoice of 2027 is <code>INV/2027/00001</code>.</p><p><strong>Example:</strong> The third invoice of 2026 in the <strong>Customer Invoices</strong> journal is <code>INV/2026/00003</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Older records can show a shorter number, such as <code>INV/2026/1</code>. Both forms are valid. New documents use 5 digits.</p></div><h2 id="when-the-number-appears" tabindex="-1">When the number appears <a class="header-anchor" href="#when-the-number-appears" aria-label="Permalink to &quot;When the number appears&quot;">​</a></h2><p>Aureus gives the number when the document is created, not when you confirm it. A draft invoice already shows its number in the list, for example <code>INV/2026/00003</code>. The number does not change when you confirm, cancel or reset the document to draft.</p><h2 id="prefixes-for-credit-notes-and-payments" tabindex="-1">Prefixes for credit notes and payments <a class="header-anchor" href="#prefixes-for-credit-notes-and-payments" aria-label="Permalink to &quot;Prefixes for credit notes and payments&quot;">​</a></h2><p>A journal can keep separate counters for credit notes and payments. Two toggles on the journal control this.</p><ul><li><strong>Dedicated Credit Note Sequence:</strong> When on, credit notes and refunds get the prefix <strong>R</strong>. A credit note in the INV journal is <code>RINV/2026/00004</code>. A vendor refund in the BILL journal is <code>RBILL/2026/00005</code>.</li><li><strong>Dedicated Payment Sequence:</strong> When on, payments get the prefix <strong>P</strong>. A payment in the BANK journal is <code>PBANK/2026/3</code>.</li></ul><p>When a toggle is off, the document uses the normal counter of the journal.</p><p>To change a toggle, go to <code>Accounting → Configurations → Accounting → Journals</code>, open the journal and use the switches in the <strong>Accounting Information</strong> tab. The journal code is the field named <strong>Sort</strong>. See <a href="./../get-started/journals.html">Journals</a>.</p><h2 id="see-and-change-the-rule" tabindex="-1">See and change the rule <a class="header-anchor" href="#see-and-change-the-rule" aria-label="Permalink to &quot;See and change the rule&quot;">​</a></h2><p>Sequences are stored in the <strong>Settings</strong> app.</p><ol><li>Go to <code>Settings → Sequences</code>.</li><li>Find the row for your journal, for example <strong>Customer Invoices</strong>.</li></ol>',20)),i(n,{src:"/images1/finance/invoice_sequences_list.png",alt:"Sequences list with Customer Invoices, Customer Invoices (Refund), Vendor Bills and Vendor Bills (Refund) rows and their next document numbers"}),e[1]||(e[1]=o('<p>The list shows these columns:</p><ul><li><strong><em>Name:</em></strong> The name of the sequence.</li><li><strong><em>Code:</em></strong> The technical identifier.</li><li><strong><em>Applies To:</em></strong> The journal. It can end with <strong>Refund</strong> or <strong>Payment</strong>.</li><li><strong><em>Company:</em></strong> The company it belongs to.</li><li><strong><em>Next Document Number:</em></strong> A preview of the next number, such as <code>INV/2026/00004</code>.</li><li><strong><em>Next Number:</em></strong> The counter value, such as 4.</li><li><strong><em>Reset Counter:</em></strong> When the counter restarts, such as <strong>Every Year</strong>.</li></ul><p>To edit a row, click <strong>Edit</strong>, change the field and click <strong>Save changes</strong>. You cannot lower <strong>Next Number</strong>. You can only raise it. See <a href="./../../general-settings/customization/sequences.html">Sequences</a> for every field.</p><h2 id="worked-example" tabindex="-1">Worked example <a class="header-anchor" href="#worked-example" aria-label="Permalink to &quot;Worked example&quot;">​</a></h2><p>Your <strong>Customer Invoices</strong> sequence shows <strong>Next Number</strong> 4.</p><ol><li>You create a new invoice. It gets <code>INV/2026/00004</code>. The sequence now shows 5.</li><li>You confirm it. The number stays <code>INV/2026/00004</code>.</li><li>You click <strong>Credit Note</strong> on it and the journal has a dedicated credit note sequence. The draft credit note gets the next number of the refund sequence, such as <code>RINV/2026/00004</code>.</li><li>You raise <strong>Next Number</strong> to 100 in the sequence. The next invoice is <code>INV/2026/00100</code>.</li></ol><h2 id="good-to-know" tabindex="-1">Good to know <a class="header-anchor" href="#good-to-know" aria-label="Permalink to &quot;Good to know&quot;">​</a></h2><ul><li>Do not try to reuse a number. Never type a number again that another document already uses.</li><li>Raise <strong>Next Number</strong> only when you must skip ahead, for example to match an older system.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./create-invoice.html">Create an invoice</a></li><li><a href="./credit-notes-and-refunds.html">Credit notes and refunds</a></li><li><a href="./../../general-settings/customization/sequences.html">Sequences</a></li><li><a href="./../get-started/journals.html">Journals</a></li></ul>',10))])}const b=t(c,[["render",l]]);export{f as __pageData,b as default};
